// Sandbox for the dreamer (src/components/dreamer) before it joins the pet on
// the real pages. Not linked from the nav.
import React, { useRef, useState } from "react";
import Dreamer from "../../components/dreamer/Dreamer";

const MODE_LABEL = {
  idle: "standing",
  walk: "walking",
  takeoff: "running… flapping… lifting",
  fly: "flying",
  land: "gliding down",
};

export default function DreamLab({ theme }) {
  const isLight = theme?.name !== "dark";
  const dreamer = useRef(null);
  const [auto, setAuto] = useState(true);
  const [follow, setFollow] = useState(false);
  const [mode, setMode] = useState("idle");

  const fg = theme?.text || "#333";
  const muted = theme?.secondaryText || "#666";

  const btn = {
    background: "transparent",
    color: fg,
    border: `1px solid ${muted}55`,
    borderRadius: 999,
    padding: "7px 16px",
    font: "inherit",
    fontSize: 14,
    cursor: "pointer",
  };
  const on = { ...btn, background: `${fg}12` };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: theme?.body,
        color: fg,
        padding: "12vh 24px 0",
        boxSizing: "border-box",
      }}
    >
      <div style={{ maxWidth: 640, margin: "0 auto" }}>
        <p style={{ color: muted, fontSize: 13, letterSpacing: 1.5, margin: 0 }}>
          DREAM LAB
        </p>
        <h1 style={{ fontSize: 40, margin: "8px 0 12px", fontWeight: 700 }}>
          The flying dream
        </h1>
        <p style={{ color: muted, lineHeight: 1.6, margin: 0 }}>
          He walks, breaks into a run, starts beating his arms like wings, and
          slowly the ground lets go. Click him to take off or land.
        </p>

        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 28 }}>
          <button style={btn} onClick={() => dreamer.current?.walk()}>
            Walk
          </button>
          <button style={btn} onClick={() => dreamer.current?.takeOff()}>
            Take off
          </button>
          <button style={btn} onClick={() => dreamer.current?.land()}>
            Land
          </button>
          <button style={btn} onClick={() => dreamer.current?.scoop()}>
            Scoop Mochi
          </button>
          <button
            style={follow ? on : btn}
            onClick={() => {
              dreamer.current?.setFollow(!follow);
              setFollow(!follow);
            }}
          >
            Follow cursor
          </button>
          <button style={auto ? on : btn} onClick={() => setAuto(!auto)}>
            Autopilot
          </button>
        </div>
        <p style={{ color: muted, fontSize: 13, marginTop: 14 }}>
          now: {MODE_LABEL[mode] || mode}
        </p>
      </div>

      <Dreamer
        ref={dreamer}
        isLight={isLight}
        autopilot={auto}
        onModeChange={setMode}
      />
    </div>
  );
}
